WITH cleaned AS (SELECT id, plan, start_date, end_date, monthly_fee, COALESCE(monthly_fee, 0) AS monthly_fee_filled, ROUND(monthly_fee * 0.85, 2) AS adjusted_monthly_fee FROM subscriptions WHERE start_date > TO_DATE('2023-09-29') AND end_date <= '2023-03-01'), ranked AS (SELECT * FROM cleaned QUALIFY RANK() OVER (PARTITION BY plan ORDER BY end_date) = 1), metrics AS (SELECT id, plan, start_date, NTILE(4) OVER (PARTITION BY MONTH(end_date), plan ORDER BY monthly_fee DESC, id) AS monthly_fee_bucket, LAST_VALUE(monthly_fee_filled) IGNORE NULLS OVER (PARTITION BY DATE_TRUNC('WEEK', start_date), plan ORDER BY monthly_fee_filled, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_monthly_fee_filled FROM ranked), with_windows AS (SELECT *, AVG(monthly_fee_bucket) OVER (PARTITION BY plan ORDER BY last_known_monthly_fee_filled, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS monthly_fee_bucket_avg_5, AVG(monthly_fee_bucket) OVER (PARTITION BY DATE_TRUNC('week', start_date), plan) AS start_date_period_avg_monthly_fee_bucket, RANK() OVER (ORDER BY monthly_fee_bucket NULLS LAST) AS monthly_fee_bucket_rank FROM metrics), summary AS (SELECT CASE WHEN start_date_period_avg_monthly_fee_bucket >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS start_date_period_avg_monthly_fee_bucket_tier, MAX(last_known_monthly_fee_filled) AS max_last_known_monthly_fee_filled, COUNT(*) AS num_rows FROM with_windows GROUP BY CASE WHEN start_date_period_avg_monthly_fee_bucket >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING num_rows >= 1) SELECT start_date_period_avg_monthly_fee_bucket_tier FROM summary ORDER BY start_date_period_avg_monthly_fee_bucket_tier NULLS FIRST LIMIT 10;
